{
  "name": "泰克 TDS1012 数字存储示波器",
  "name_en": "Tektronix TDS1012 Digital Storage Oscilloscope",
  "manufacturer": "Tektronix",
  "description": "一款 100 MHz、2 通道数字存储示波器，用于采集和观察电信号波形，并进行频率、均值、最小值、最大值等基础测量。该设备支持触发、自动设置、自动校准和波形数据读取，适合电子实验与信号调试。",
  "description_en": "A 100 MHz, 2-channel digital storage oscilloscope used to capture and visualize electrical waveforms and perform basic measurements such as frequency, mean, minimum, and maximum. It supports triggering, autoset, autocalibration, and waveform data transfer for electronics experiments and signal debugging.",
  "actions": [
    {
      "action_name": "auto-acquire_curve_async",
      "description": "异步采集示波器波形数据。",
      "description_en": "Asynchronously acquire waveform data from the oscilloscope."
    },
    {
      "action_name": "auto-acquire_parameters_async",
      "description": "异步读取波形采集参数。",
      "description_en": "Asynchronously read waveform acquisition parameters."
    },
    {
      "action_name": "auto-autocal_async",
      "description": "异步执行示波器自动校准。",
      "description_en": "Asynchronously perform oscilloscope autocalibration."
    },
    {
      "action_name": "auto-autoset_async",
      "description": "异步执行自动设置以获得稳定波形显示。",
      "description_en": "Asynchronously run autoset to obtain a stable waveform display."
    },
    {
      "action_name": "auto-data_setup_async",
      "description": "异步设置波形数据传输编码方式。",
      "description_en": "Asynchronously configure waveform data transfer encoding."
    },
    {
      "action_name": "auto-forcetrigger_async",
      "description": "异步强制产生一次触发事件。",
      "description_en": "Asynchronously force a trigger event."
    },
    {
      "action_name": "auto-idn_async",
      "description": "异步读取设备身份信息。",
      "description_en": "Asynchronously read the device identification."
    },
    {
      "action_name": "auto-initiate_async",
      "description": "异步启动采集。",
      "description_en": "Asynchronously initiate acquisition."
    },
    {
      "action_name": "auto-measure_frequency",
      "description": "测量信号频率。",
      "description_en": "Measure the signal frequency."
    },
    {
      "action_name": "auto-measure_maximum",
      "description": "测量信号最大值。",
      "description_en": "Measure the signal maximum."
    },
    {
      "action_name": "auto-measure_mean",
      "description": "测量信号均值。",
      "description_en": "Measure the signal mean."
    },
    {
      "action_name": "auto-measure_minimum",
      "description": "测量信号最小值。",
      "description_en": "Measure the signal minimum."
    },
    {
      "action_name": "auto-triggerlevel_async",
      "description": "异步将触发电平设置为信号范围的 50%。",
      "description_en": "Asynchronously set the trigger level to 50% of the signal range."
    },
    {
      "action_name": "auto-initiate",
      "description": "启动采集。",
      "description_en": "Initiate acquisition."
    },
    {
      "action_name": "auto-idn",
      "description": "读取设备身份信息。",
      "description_en": "Read the device identification."
    },
    {
      "action_name": "auto-autoset",
      "description": "执行自动设置以获得稳定波形显示。",
      "description_en": "Run autoset to obtain a stable waveform display."
    },
    {
      "action_name": "auto-autocal",
      "description": "执行示波器自动校准。",
      "description_en": "Perform oscilloscope autocalibration."
    },
    {
      "action_name": "auto-datasource",
      "description": "获取或设置波形采集数据源通道。",
      "description_en": "Get or set the waveform acquisition data source channel."
    },
    {
      "action_name": "auto-acquire_parameters",
      "description": "读取波形采集参数。",
      "description_en": "Read waveform acquisition parameters."
    },
    {
      "action_name": "auto-data_setup",
      "description": "设置波形数据传输编码方式。",
      "description_en": "Configure waveform data transfer encoding."
    },
    {
      "action_name": "auto-acquire_curve",
      "description": "采集示波器波形数据。",
      "description_en": "Acquire waveform data from the oscilloscope."
    },
    {
      "action_name": "auto-forcetrigger",
      "description": "强制产生一次触发事件。",
      "description_en": "Force a trigger event."
    },
    {
      "action_name": "auto-triggerlevel",
      "description": "将触发电平设置为信号范围的 50%。",
      "description_en": "Set the trigger level to 50% of the signal range."
    },
    {
      "action_name": "auto-trigger",
      "description": "获取或设置触发状态。",
      "description_en": "Get or set the trigger state."
    },
    {
      "action_name": "auto-horizontal_division",
      "description": "获取或设置水平时基每格时间。",
      "description_en": "Get or set the horizontal time-base per division."
    },
    {
      "action_name": "auto-number_averages",
      "description": "获取或设置平均次数。",
      "description_en": "Get or set the number of averages."
    }
  ],
  "tag_hints": [
    "digital storage oscilloscope",
    "waveform acquisition",
    "2-channel oscilloscope",
    "100 MHz bandwidth",
    "trigger control",
    "electrical signal measurement",
    "Tektronix TDS1000 series"
  ]
}

